arguments.command:
curl -s -X POST https://slack.com/api/users.list -d "token=<TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:',d.get('error'),d.get('msg')); sys.exit(1)
for u in d['members']:
    name=u.get('profile',{}).get('display_name') or u.get('real_name','')
    if 'maya' in name.lower() or 'chen' in name.lower():
        print(u['id'], name, '| real:', u.get('real_name'))
"

